DATA=[
dict(path='/claims/insurance-claim-form-writing',slug='claim-form-writing',cat='청구서류',title='보험금 청구서 작성법, 수술일·진단명·사고내용 기재 예시',desc='보험금 청구서 작성 시 발병일과 수술일, 진단명과 사고내용을 구분하는 방법입니다. 보험사 양식의 항목을 병원 서류와 대조하고, 모르는 내용을 추측해 적지 않는 작성 순서와 가상 예시를 정리합니다.',parents=['/claims/surgery-claim-documents','/claims/insurance-claim-method'],intent='청구서 자체의 항목 작성과 오류 예방. 병원 서류 목록·발급 안내와 구분.',sources=[(CHUBB,'처브 보험금 청구 서류·양식','현재 제공되는 회사 양식으로 이동'),(FORM,'처브 개인보험 청구서 예시','사고일·내원 경위·진단명 등 실제 항목 확인')],body=[
h('보험금 청구서는 병원 서류를 보고 작성합니다')+p('보험금 청구서 작성법에서 가장 헷갈리는 부분은 날짜와 사고내용입니다. 질병 치료인데 사고를 새로 만들어 적거나, 발병일 칸에 수술일을 무조건 넣을 필요는 없습니다. 본인이 가입한 보험사의 현재 양식을 먼저 받아 항목 이름을 읽고, 진단서·수술확인서·영수증과 대조하세요.')+p('회사마다 양식과 앱 입력 항목이 다릅니다. '+a(FORM,'처브 개인보험 청구서')+'에는 사고일(발병일), 사고·내원 경위, 병원명과 진단명 등의 칸이 있습니다. 이 예시의 항목을 다른 회사에도 그대로 적용하지 말고, 제출할 회사의 안내를 기준으로 작성합니다.'),
h('발병일·진료일·수술일을 한 날짜로 맞추지 마세요')+table(['항목','확인할 자료','잘 모를 때'],[['발병일·사고일','실제 증상 발생 또는 사고 사실과 양식 안내','증상이 시작된 날이 불명확하면 보험사에 기재 기준 문의'],['진료일·입퇴원일','병원 진료·입퇴원 확인 자료','수술 날짜와 입원 기간을 각각 대조'],['수술일','수술확인서·수술기록','실제 수술받은 날짜 확인'],['진단명','병원 발급 서류의 진단명','영수증 항목명으로 질병을 추정하지 않기']])+p('양식에 수술일 칸이 없더라도 사고일 칸을 마음대로 바꿔 해석하지 않습니다. 필요하면 내원 경위나 별도 설명에 수술일을 적을 수 있는지 문의하세요. 여러 날 치료받았다면 어느 진료를 이번에 청구하는지 먼저 정리하면 입력 누락을 줄일 수 있습니다.'),
h('사고내용은 사실의 순서로 짧게 적습니다')+p('질병 청구라면 진료를 받은 이유, 의료기관, 확인된 진단명, 받은 치료를 간단히 연결합니다. 지급을 받기 위해 원인·진단·치료 목적을 확대하거나 의료진이 적지 않은 표현을 보태지 마세요. 상해라면 본인이 아는 사고 시점·장소·경위를 사실대로 쓰고, 불확실한 부분은 확인 후 보완합니다.')+ul(['병원 서류의 진단명과 청구서 진단명이 같은지 대조','이번 청구와 과거 접수 건이 같은 사고·질병인지 확인','특약 선택이 어렵다면 계약의 청구 가능 항목을 보험사에 문의','신청인·수익자·지급계좌 정보는 회사 안내에 따라 확인']),
h('가상 기재 예시: 담낭 수술을 받은 경우')+p('다음은 실제 환자 기록이 아닌 작성 연습입니다. A씨가 10월 3일 진료를 받고 10월 6일 담낭절제술을 받았으며, 발병일은 정확히 기억하지 못한다고 가정합니다. 내원 경위에는 “복부 불편감으로 진료 후 병원 서류에 기재된 진단에 따라 10월 6일 수술받음”처럼 본인이 확인한 사실만 씁니다. 진단명 칸은 발급받은 서류와 맞춥니다.')+p('이때 10월 6일을 발병일이라고 단정하지 말고, 발병일을 모를 때의 입력 방법을 보험사에 문의합니다. 이 문장을 복사해 모든 청구에 쓰는 것이 아니라 자신의 사실·서류·양식에 맞게 바꿔야 합니다.'),
h('전송 전에는 개인정보와 첨부자료를 따로 확인하세요')+ul(['사용할 보험사와 청구 대상 계약이 맞는가','날짜·병원·진단명에 오타가 없는가','서명·동의 등 필요한 칸이 빠지지 않았는가','계좌 명의와 수익자 요건을 확인했는가','첨부 파일이 열리고 다른 사람 자료가 섞이지 않았는가'])+p('접수 후 잘못 쓴 내용을 알았다면 같은 건을 새로 여러 번 제출하기보다 접수번호로 정정·보완 경로를 확인합니다. 청구서 작성과 별개로 어떤 병원 서류가 필요한지는 '+a('/claims/surgery-claim-documents','수술비 청구서류')+'에서, 접수 경로는 '+a('/claims/insurance-claim-method','보험금 청구 방법')+'에서 이어 확인할 수 있습니다.'),
h('문의 문장: 날짜를 모를 때')+'<blockquote>질병 청구서의 발병일을 정확히 기억하지 못합니다. 진료일과 수술일은 서류로 확인되는데, 해당 칸은 어떻게 기재하고 어떤 자료로 보완하면 되나요?</blockquote>'+p('주민등록번호·계좌·서명·진료자료는 공개 댓글에 올리지 말고 보험사의 공식 접수 경로로만 전달하세요. 서류를 모두 제출해도 지급 여부는 계약과 심사 결과에 따라 결정됩니다.')]),
dict(path='/claims/primary-secondary-diagnosis-surgery-claim',slug='primary-secondary-diagnosis',cat='청구서류',title='주상병·부상병 차이, 수술비 청구 시 진단명 확인 기준',desc='주상병과 부상병은 진료에서의 상병 구분입니다. 부상병이라는 이유만으로 수술비 지급 여부를 판단하지 않고, 수술 목적·실제 수술명·가입 특약을 함께 확인하는 방법을 정리합니다.',parents=['/surgery-benefit/surgery-classification','/surgery-benefit/gallbladder-surgery-benefit'],intent='주상병과 부상병의 역할 및 수술과의 연결 확인. 종별 분류표·질병별 수술 설명과 구분.',sources=[(CODE,'심평원 요양급여 청구 작성요령','주상병·부상병·배제된 상병의 구분'),(CHUBB,'보험사 수술비 청구자료 예시','실제 제출 양식과 필요서류 확인')],body=[
h('주상병·부상병은 보험금 지급 순위를 뜻하지 않습니다')+p('주상병·부상병 차이를 볼 때는 진료자료의 분류와 개인 보험계약을 나누어 생각해야 합니다. 주상병이라고 무조건 수술비가 나오거나 부상병이면 제외되는 것은 아닙니다. 어떤 질병을 치료하기 위해 어떤 수술을 받았는지, 그 행위가 가입 특약의 지급 기준에 해당하는지가 별도 확인 대상입니다.')+p(a(CODE,'심평원 청구 작성요령')+'에서 주상병은 진료기간에 치료·검사 요구가 가장 컸던 상병, 부상병은 함께 있거나 발생하여 진료에 영향을 준 상병으로 구분합니다. 이 설명은 건강보험 청구자료의 분류를 이해하기 위한 것으로 민영보험 지급 기준을 대신하지 않습니다.'),
h('세 가지 표시를 구분해서 읽으세요')+table(['구분','이해할 점','청구 전 확인'],[['주상병','해당 진료의 중심이 된 상병','실제 수술 원인과 연결되는지 확인'],['부상병','함께 진료에 영향을 준 상병','동반 질환인지 수술 대상인지 기록 확인'],['배제된 상병','검토했으나 최종적으로 배제된 상병','확정 진단과 혼동하지 않기']])+p('같은 사람이라도 진료기간이나 치료 목적에 따라 자료에 표시되는 상병이 달라질 수 있습니다. 오래된 조회내역의 첫 번째 병명만 보고 이번 수술 진단명을 결정하지 말고, 해당 수술 당시 발급 자료와 수술기록을 확인하세요.'),
h('수술비 청구에서는 질병명과 수술명을 연결합니다')+ul(['수술확인서의 진단명과 수술명·시행일 확인','여러 질병이 적혀 있으면 각각 어떤 치료를 받았는지 확인','수술비 특약의 수술 정의·분류표·제외항목 확인','동시에 여러 수술을 받았다면 복수 수술 지급 조항을 별도 확인'])+p('진단명이 두 개라고 수술비도 두 번 나오는 것은 아닙니다. 반대로 부상병에 해당하는 질병에 대한 수술이 실제로 있었다면 상병 순서만 보고 포기할 이유도 없습니다. 실제 시행 행위와 해당 계약 조항을 연결해 질문해야 합니다. 종별 수술비를 확인한다면 '+a('/surgery-benefit/surgery-classification','수술분류표 안내')+'를 함께 보세요.'),
h('가상 예시: 담낭 질환과 다른 질환이 함께 적힌 경우')+p('A씨의 진료자료에 담낭 질환과 다른 동반 질환이 함께 적혀 있고 실제로는 담낭절제술을 받았다고 가정합니다. 확인할 것은 두 질병이 적힌 순서만이 아니라 수술기록상 수술 목적과 시행 내용입니다. 동반 질환은 약물치료만 받았는지, 별도 수술도 있었는지 구분합니다.')+p('이 예시만으로 특정 종수나 지급 횟수를 정할 수는 없습니다. '+a('/surgery-benefit/gallbladder-surgery-benefit','담낭절제술 수술비 안내')+'와 자신의 특약을 대조하고, 보험사가 추가 자료를 요구하면 어떤 사실이 불명확한지 먼저 확인하세요.'),
h('병명 순서 변경을 요구하기 전에 물어볼 내용')+p('보험금을 받기 위해 진단 순서를 임의로 바꿔 달라고 요청하지 마세요. 서류에 사실과 다른 내용이 의심된다면 병원에 실제 진료기록을 기준으로 확인·정정 가능 여부를 묻습니다. 보험사에는 어떤 수술과 어떤 지급 조항을 검토하는지, 추가 확인할 자료가 무엇인지 요청합니다.')+'<blockquote>수술확인서에 여러 진단명이 있습니다. 이번 수술의 대상 질병과 시행 수술명을 어떤 자료로 확인하면 되나요? 주상병·부상병 표시 외에 심사에 필요한 항목을 알려 주세요.</blockquote>'+p('진단서 발급, 의학적 진단, 건강보험 청구 분류와 민영보험금 심사는 각기 다른 절차입니다. 조회 화면의 병명을 직접 수정하거나 추정한 진단코드를 청구서에 넣지 않습니다.')]),
dict(path='/claims/cataract-slitlamp-records',slug='cataract-slitlamp-records',cat='청구서류',title='백내장 세극등검사 결과지, 사진·판독기록 발급 전 확인',desc='백내장 보험청구에서 세극등검사 결과지나 사진을 요청받았다면 검사일·좌우 눈·요청 자료 범위를 먼저 확인하세요. 결과지와 영상의 차이, 병원 보유 여부, 추가자료 제출 순서를 정리합니다.',parents=['/surgery-benefit/cataract-surgery-benefit','/claims/cataract-surgery-claim-documents'],intent='세극등 자료의 결과·사진·판독 범위 확인. 일반 백내장청구 목록과 구분.',sources=[(SAMSUNG,'삼성화재 질병·상해 필요서류','실손의료비의 백내장 추가 검사자료 예시'),(LAW,'의료법 시행규칙 제15조','검사소견 등 기록 종류별 보존 규정')],body=[
h('세극등검사 결과지와 검사 사진은 같은 자료가 아닙니다')+p('백내장 세극등검사 결과지를 요청받았다면 보험사 안내에 적힌 자료명을 그대로 확인하세요. 검사 결과를 적은 기록, 판독·진료기록, 촬영한 사진·영상은 형태와 내용이 다를 수 있습니다. 병원에 “백내장 서류 전부”라고 요청하기보다 필요한 검사일과 좌우 눈, 자료 형태를 특정하면 중복 발급을 줄일 수 있습니다.')+p(a(SAMSUNG,'삼성화재 필요서류 안내')+'는 실손의료비의 추가자료 예로 백내장 세극등현미경검사결과지·수술기록지 등을 제시합니다. 모든 보험사·모든 백내장 청구에서 동일한 자료가 필수라는 뜻은 아닙니다. 본인의 접수 건에서 받은 요청을 기준으로 준비합니다.'),
h('보험사 요청 문구에서 네 가지를 확인하세요')+table(['확인 항목','질문 예시','병원에 전달할 정보'],[['대상 기간','수술 전 어느 날짜 검사가 필요한가','요청 검사일 또는 기간'],['대상 눈','오른쪽·왼쪽·양안 중 무엇인가','수술일과 좌우 눈'],['자료 형태','결과기록만인가, 사진도 포함인가','정확한 자료명'],['보완 목적','어떤 내용을 추가로 확인하려는가','검사·진료기록의 필요한 범위']])+p('여러 번 검사했다면 가장 최근 결과만 보내면 되는지 확인합니다. 서로 다른 날짜에 양안을 수술했다면 검사일과 수술일을 눈별로 나누어 표시해 두세요. 사진 파일명만으로 날짜·대상 눈이 확인되지 않으면 병원에 식별 정보가 있는 자료를 문의합니다.'),
h('사진이 없다고 임의의 다른 검사를 대체 제출하지 않습니다')+p('의무기록 창구에 세극등 검사 기록과 촬영 자료가 각각 보관되어 있는지 문의하세요. 진료가 이루어졌다는 사실만으로 사진 파일이 반드시 존재한다고 가정하면 안 됩니다. 병원이 보유한 기록의 형태와 발급 가능 범위를 확인하고, 요청 자료가 없다면 그 사정을 보험사에 전달해 대체자료를 인정하는지 문의합니다.')+p('다른 검사결과나 새로 받은 검사로 과거 검사 자료를 임의 대체하지 마세요. 추가 검사가 의학적으로 필요한지는 의료진이 판단할 사항입니다. 기록 발급을 위해 불필요한 검사를 받는 방향으로 결정할 필요는 없습니다.'),
h('가상 예시: 결과지는 받았는데 사진을 추가 요청한 경우')+p('A씨가 오른쪽 백내장 수술 후 검사결과 기록을 제출했지만 사진 자료를 추가 요청받았다고 가정합니다. 먼저 기존 제출 파일에 사진이 빠진 것인지, 병원에서 사진을 별도로 발급하는지, 해당 검사에서 사진 자체를 보유하는지 순서대로 확인합니다. 사진이 없다는 안내를 받았다면 그 내용을 보험사에 알리고 다음 제출 범위를 확인합니다.')+p('추가자료 요청만으로 지급 거절이 확정된 것은 아니며 자료를 보냈다고 지급이 보장되는 것도 아닙니다. 심사 진행 상태와 필요한 보완 항목을 접수번호로 구분해 확인하세요.'),
h('첨부 전 검사일·눈·페이지를 마지막으로 대조하세요')+ul(['요청한 검사일과 제출 자료의 날짜가 일치하는가','좌우 눈과 실제 수술일을 구분했는가','여러 장 중 판독·결과가 적힌 페이지가 빠지지 않았는가','사진이나 스캔의 글자가 읽히고 잘리지 않았는가','다른 사람의 자료와 개인정보가 섞이지 않았는가'])+p('전체 준비 목록은 '+a('/claims/cataract-surgery-claim-documents','백내장 수술 청구서류')+'로, 종별·실손의 판단 차이는 '+a('/surgery-benefit/cataract-surgery-benefit','백내장 수술비 안내')+'로 연결됩니다. 오래된 자료라면 기록 종류별 보존기간과 실제 보유 여부도 별도로 확인하세요.')]),
dict(path='/claims/past-surgery-history-lookup',slug='past-surgery-history',cat='청구서류',title='수술내역 조회 방법, 심평원 진료정보와 병원 수술기록지 차이',desc='과거 수술 병원과 날짜가 기억나지 않을 때 심평원 내 진료정보 열람을 활용하는 방법입니다. 최대 5년 진료내역 조회와 보험청구용 수술기록지 발급의 차이, 조회되지 않을 때의 확인 순서를 정리합니다.',parents=['/claims/surgery-claim-documents','/surgery-benefit/surgery-classification'],intent='과거 수술 병원·날짜를 찾는 조회 단계. 서류 발급·보험가입내역 조회와 구분.',sources=[(HIRA,'심평원 내 진료정보 열람','최대 5년 조회 범위와 증빙자료 활용 제한'),(LAW,'의료법 시행규칙 제15조','병원 보존기록과 조회정보의 구분')],body=[
h('수술내역 조회는 병원과 날짜를 찾는 데서 시작합니다')+p('수술내역 조회가 필요한 이유가 보험청구라면, 과거 진료를 찾는 일과 제출용 수술기록지를 발급받는 일을 나누세요. 심평원에서 보이는 정보는 병원의 전체 의무기록 원본이 아닙니다. 기억나지 않는 병원·진료 시점을 찾는 단서로 활용하고 실제 수술명·수술일은 해당 병원 기록으로 확인합니다.')+p(a(HIRA,'심평원 내 진료정보 열람')+'은 본인의 최대 5년 전 진료내역까지 확인할 수 있다고 안내합니다. 또한 해당 열람정보는 근무처·보험회사 등에 제출하는 증빙자료로 활용할 수 없다고 명시합니다. 조회 화면을 수술확인서나 수술기록지 대신 제출하는 방식으로 안내할 수는 없습니다.'),
h('심평원 진료정보와 수술기록지의 역할을 구분하세요')+table(['자료','활용 목적','한계'],[['심평원 내 진료정보','과거 진료기관과 시점을 찾는 단서','보험회사 제출용 증빙 아님'],['병원 수술확인서','확인서에 적힌 진단·수술·날짜 확인','필요 항목이 포함되는지 확인'],['병원 수술기록지','실제 수술의 구체적 시행 내용 확인','병원 보유 여부와 필요한 범위 확인']])+p('열람정보는 요양급여 청구명세서 기반입니다. 비급여만 받은 치료나 모든 의료행위, 평생의 수술이 빠짐없이 보인다고 기대하지 마세요. 조회 결과에 병원이 없다는 것과 수술을 받지 않았다는 것은 같은 결론이 아닙니다.'),
h('공식 메뉴에서 본인 진료정보를 확인하는 순서')+ul(['심평원 공식 홈페이지의 내 진료정보 열람으로 이동','안내된 이용 범위·동의·본인확인 절차 확인','조회 가능한 기간에서 의료기관과 진료일 확인','해당 병원 의무기록 창구에 수술기록 보유 여부 문의','보험사 요청 항목을 확인한 뒤 필요한 서류만 발급'])+p('인터넷 검색 결과의 대행 조회 링크에 신분증이나 인증정보를 전달하지 마세요. 가족·대리 조회는 본인 조회와 요건이 다를 수 있으므로 공식 안내를 별도로 읽어야 합니다. 이 글은 개인 계정에 로그인하거나 개인 진료내역을 대신 조회하는 서비스가 아닙니다.'),
h('조회되지 않을 때는 기간과 기관을 먼저 좁힙니다')+p('먼저 조회 가능한 기간 밖의 수술인지, 실제 수술한 지점과 기억하는 병원이 같은지 확인합니다. 본인이 보관한 영수증·예약 문자·퇴원서류·결제내역이 있다면 병원과 날짜를 찾는 보조 단서로 활용할 수 있습니다. 결제 금액만으로 수술 종류나 보험 지급항목을 단정하지 않습니다.')+p('병원을 찾았다면 수술명·입퇴원일·자료 보유 여부를 문의하세요. 폐업했다면 '+a('/claims/closed-hospital-records-request','폐업 병원 기록 확인 절차')+'를 따로 확인하고, 오래된 자료는 '+a('/claims/operative-record-retention-period','수술기록지 보존기간')+'에서 기록별 차이를 볼 수 있습니다.'),
h('가상 예시: 병원은 찾았지만 수술명이 불명확한 경우')+p('A씨가 3년 전 입원한 병원을 열람정보에서 찾았다고 가정합니다. 조회된 진료일만으로 수술일을 적지 않고 병원에 당시 수술확인서 발급 가능 여부를 묻습니다. 보험사에는 청구 대상 특약과 필요한 자료를 확인한 뒤 발급합니다. 조회 화면에 적힌 진료비와 실제 보험금도 동일한 금액으로 보지 않습니다.')+p('전체 서류 준비는 '+a('/claims/surgery-claim-documents','수술비 청구서류')+'와 연결해 확인하세요. 오래된 진료를 찾았더라도 청구권 기간과 계약 조건은 별도로 검토해야 합니다.')]),
dict(path='/claims/operative-record-retention-period',slug='operative-record-retention',cat='청구서류',title='수술기록지 보존기간, 오래된 수술 서류 발급 전 확인',desc='수술기록은 의료법 시행규칙상 10년 보존 대상입니다. 검사기록·진단서 부본의 기간 차이, 기간이 지난 자료의 실제 보유 여부와 보험금 청구기간을 나누어 확인하는 방법을 정리합니다.',parents=['/claims/surgery-claim-documents','/claims/closed-hospital-records-request','/claims/insurance-claim-limitation'],intent='의료기관 기록 종류별 보존 의무와 실제 발급 가능성. 보험금 소멸시효와 구분.',sources=[(LAW,'의료법 시행규칙 제15조','기록별 보존기간과 계속 진료 시 연장 규정'),(HIRA,'심평원 내 진료정보 열람','공공 조회기간과 병원 보존기간의 구분')],body=[
h('수술기록지 보존기간은 10년, 다른 서류와 다릅니다')+p('수술기록지 보존기간을 검색했다면 먼저 어떤 기록이 필요한지 정하세요. 의료법 시행규칙 제15조는 수술기록의 보존기간을 10년으로 정합니다. 진단서·검사결과·진료기록은 각각 다른 항목이므로 “병원 서류는 전부 10년”으로 묶으면 안 됩니다. 실제 발급할 자료명과 해당 진료 시점을 병원에 알려 확인하세요.'),
h('기록 종류별 법정 기간을 나누어 봅니다')+table(['기록 종류','규정상 보존기간','발급 문의 시 구분'],[['수술기록','10년','실제 시행 수술의 기록'],['진료기록부','10년','진료 경과·내용'],['검사내용 및 검사소견기록','5년','검사 종류·검사일'],['방사선 사진·영상 및 소견서','5년','영상과 소견 자료'],['진단서 등 부본','3년','이미 발급한 증명서의 부본'],['처방전','2년','처방한 약·일자 확인']])+p('이 표는 '+a(LAW,'의료법 시행규칙 제15조')+'의 항목을 간추린 것입니다. 같은 조는 계속적인 진료에 필요하면 정해진 기간의 범위에서 1회 연장할 수 있도록 규정합니다. 개별 병원의 모든 자료가 표의 기간만큼 반드시 온라인에서 발급된다는 뜻은 아닙니다.'),
h('기간이 지났다고 자동 폐기되었다고 단정하지 마세요')+p('법정 보존기간과 현재 병원이 자료를 보유하고 있는지는 다른 질문입니다. 기간이 지난 기록도 병원에 남아 있는지 문의할 수 있지만, 확인 없이 발급 가능하다고 약속할 수는 없습니다. 전산 이전, 보관 형태, 해당 기록의 종류에 따라 창구에서 확인하는 절차가 달라질 수 있습니다.')+p('반대로 진단서 부본 보존기간이 지났다고 수술기록까지 없다고 판단할 수는 없습니다. 과거 발급본 사본을 찾는 것인지 보유한 의무기록을 바탕으로 증명서 발급을 문의하는 것인지 구분해 설명하세요. 새 발급의 가능 여부와 필요한 진료 절차는 병원이 판단합니다.'),
h('병원에 전화하기 전 준비할 체크리스트')+ul(['대략적인 수술 연도와 당시 병원명·지점','수술 부위 또는 기억하는 수술명','필요한 자료가 수술기록·검사·증명서 중 무엇인지','보험사에서 요청한 항목과 대상 진료기간','본인·대리 발급에 필요한 서류와 방문 여부'])+'<blockquote>과거 수술 관련 보험청구 자료를 준비하고 있습니다. 해당 연도의 수술기록과 검사기록이 남아 있는지, 필요한 부분을 발급받는 절차와 비용을 알려 주세요.</blockquote>',
h('가상 예시: 8년 전 수술의 진단서 사본이 필요한 경우')+p('A씨가 8년 전 수술 당시 발급했던 진단서 사본을 찾는 상황을 가정합니다. 진단서 부본의 기간과 수술기록의 기간을 구분해, 병원에 어떤 자료가 보유되어 있는지부터 묻습니다. 진단서 사본이 없더라도 수술기록이 있는지 별도로 확인할 수 있습니다. 다만 다른 자료를 보험사가 대체 인정할지는 접수 건별로 문의해야 합니다.'),
h('수술기록 보존기간과 보험금 청구기간은 별도입니다')+p('기록이 남아 있다는 사실만으로 오래된 보험금 청구가 모두 가능한 것은 아닙니다. 또한 심평원에서 최대 5년 진료내역을 조회할 수 있다는 안내는 병원의 수술기록 보존기간을 5년으로 줄이는 규정이 아닙니다. 자료 보유, 공공 조회, 보험금 청구권의 기간을 각각 확인하세요.')+p('청구기간은 '+a('/claims/insurance-claim-limitation','보험금 청구기간 확인')+'에서, 병원이 폐업했다면 '+a('/claims/closed-hospital-records-request','폐업 병원 의무기록 문의')+'에서 이어 볼 수 있습니다. 제출할 자료 종류가 정해지지 않았다면 '+a('/claims/surgery-claim-documents','수술비 청구서류')+'부터 확인하면 됩니다.')]),
dict(path='/surgery-benefit/anal-fissure-surgery-benefit',slug='anal-fissure-surgery',cat='수술비',title='치열 수술비, 내괄약근절개술과 치핵 수술의 차이',desc='치열 수술비는 치핵 수술비와 같은 말로 판단하면 안 됩니다. 진단명과 내괄약근절개술 등 실제 수술명을 구분하고, 실손·질병수술비·종수술비 약관과 청구자료를 확인하는 순서를 정리합니다.',parents=['/surgery-benefit/hemorrhoid-surgery-benefit','/claims/hemorrhoid-surgery-claim-documents'],intent='치열과 실제 치열 수술의 보험 확인. 기존 치핵·치루의 병태 및 수술과 독립.',sources=[(FISSURE,'인천세종병원 치열 질환백과','치열의 의미와 내괄약근절개술 등 치료 설명'),(HEM,'분당서울대학교병원 치핵 안내','치질 통칭과 치핵의 구분'),(CHUBB,'보험금 청구서류 공식 안내','계약 보험사의 필요자료 확인을 위한 예시')],body=[
h('치열 수술비는 정확한 진단명과 수술명부터 확인합니다')+p('치열 수술비를 확인할 때 “치질 수술”이라는 말만으로 치핵 수술과 같은 보험금을 예상하지 마세요. 치열과 치핵은 서로 다른 질환이며 실제 수술 방법도 구분해야 합니다. 수술확인서의 진단명·수술명·수술일을 확인하고 가입한 실손보험, 질병수술비, 종수술비 특약을 각각 대조하는 것이 출발점입니다.')+p(a(FISSURE,'인천세종병원 치열 안내')+'는 치열을 항문 안쪽 피부가 찢어지는 질환으로 설명하며 만성 치열에서 내괄약근절개술 등 수술적 치료가 이루어질 수 있다고 안내합니다. 이 글은 개인에게 특정 치료를 권하거나 수술 필요성을 판단하는 안내가 아닙니다.'),
h('치열·치핵이라는 진단과 수술 행위를 구분하세요')+table(['구분','확인할 내용','보험 확인에서 주의할 점'],[['치열','진단된 질병명과 실제 치료','치핵절제술을 받았다고 바꿔 적지 않기'],['치핵','치핵에 대한 진단·시행 수술','치열과 같은 질환으로 묶지 않기'],['여러 질환 동반','각 질환에 어떤 치료를 했는지','진단명 개수와 지급 횟수를 동일하게 보지 않기']])+p(a(HEM,'분당서울대학교병원 안내')+'는 치질이라는 통칭에 치핵·치열·치루가 포함될 수 있다고 설명합니다. 일상적으로 쓰는 표현과 병원 서류의 정확한 진단명이 다를 수 있으므로, 본인의 자료에 적힌 명칭을 기준으로 문의하세요.'),
h('실손·질병수술비·종수술비를 한 번에 결론 내리지 않습니다')+table(['담보','대조할 내용','피할 판단'],[['실손의료비','가입 시기·세대·보상 제외·급여/비급여·자기부담 조항','실제 지출 전액 보상으로 계산'],['질병수술비','수술 정의·대상 질병·제외 조항','수술명이 있다는 이유로 자동 지급 판단'],['종수술비','해당 계약의 수술분류표·행위·동시수술 조항','인터넷 표의 종수를 그대로 적용']])+p('특히 항문·직장 질환 관련 제외 또는 보상 범위 조항이 있는지 본인 약관에서 확인해야 합니다. 이 글은 특정 보험사의 약관을 모든 계약에 적용하거나 치열 수술을 일률적인 종수로 분류하지 않습니다. 약관에서 찾지 못하면 보험사에 해당 조항과 분류 근거를 요청하세요.'),
h('내괄약근절개술 청구자료에서 확인할 항목')+ul(['진단명과 질병분류기호가 확인되는 병원 자료','실제 시행 수술명·수술일이 적힌 확인 자료','실손 청구 시 영수증·세부내역 등 회사 요청자료','수술 내용이 불명확할 때 추가 요청받은 수술기록','동시에 다른 수술을 받았다면 각각의 행위와 날짜'])+p('목록의 모든 서류를 처음부터 유료 발급할 필요는 없습니다. 먼저 본인 보험사의 현재 필요서류를 확인하고 기본 자료로 부족한 항목만 보완하세요. 수술확인서만으로 확인되는지, 구체적 기록이 필요한지는 접수 건과 회사 안내에 따라 달라질 수 있습니다.'),
h('가상 예시: 치열과 치핵이 함께 적힌 경우')+p('A씨의 자료에 치열과 치핵이 함께 적혀 있지만 실제 수술명은 내괄약근절개술이라고 가정합니다. 두 진단이 있다는 이유로 수술비 두 번을 계산하지 않고, 실제로 치핵 관련 수술도 함께 이루어졌는지 병원 기록을 확인합니다. 보험사에는 가입 특약과 시행 수술을 대조해 지급 여부·종수·횟수의 근거를 요청합니다.')+p('수술확인서에 “항문 수술”처럼 넓게 적혀 있다면 본인이 진단명이나 수술명을 추정해 바꾸지 않습니다. 의료기록을 근거로 구체적인 행위가 확인되는 자료를 문의하세요.'),
h('치열 수술 후 보험사에 물어볼 문장')+'<blockquote>치열 진단으로 서류에 기재된 수술을 받았습니다. 제 계약의 실손의료비와 수술비 특약에서 검토할 조항, 보상 제외 여부, 필요한 추가자료를 알려 주세요. 종수술비라면 적용 분류의 근거도 확인하고 싶습니다.</blockquote>'+p('비교 대상이 치핵 수술이라면 '+a('/surgery-benefit/hemorrhoid-surgery-benefit','치핵 수술비 안내')+'를, 기본 서류 구성은 '+a('/claims/hemorrhoid-surgery-claim-documents','항문 수술 청구서류를 확인할 때의 점검사항')+'을 함께 보되 치핵의 판단을 치열에 그대로 옮기지 마세요. 수술분류표의 구조는 '+a('/surgery-benefit/surgery-classification','수술분류표 안내')+'에서 확인할 수 있습니다.')])
]
